-- MySQL 8.0 after V012. Shared database coordination metadata only; no business ownership transfer.
-- Stop Academic/Teaching writes during migration. Historical terminal rows remain unverified.
SET @lc_result_sql=(SELECT IF(COUNT(*)=0,'ALTER TABLE evaluation_states ADD COLUMN source_revision BIGINT NOT NULL DEFAULT 0','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='evaluation_states' AND column_name='source_revision');
PREPARE lc_result_stmt FROM @lc_result_sql;EXECUTE lc_result_stmt;DEALLOCATE PREPARE lc_result_stmt;
SET @lc_result_sql=(SELECT IF(COUNT(*)=0,'ALTER TABLE enrollments ADD COLUMN completion_result_id BIGINT NULL','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='enrollments' AND column_name='completion_result_id');
PREPARE lc_result_stmt FROM @lc_result_sql;EXECUTE lc_result_stmt;DEALLOCATE PREPARE lc_result_stmt;
SET @lc_result_sql=(SELECT IF(COUNT(*)=0,'ALTER TABLE enrollments ADD COLUMN completion_result_revision BIGINT NULL','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='enrollments' AND column_name='completion_result_revision');
PREPARE lc_result_stmt FROM @lc_result_sql;EXECUTE lc_result_stmt;DEALLOCATE PREPARE lc_result_stmt;
CREATE TABLE IF NOT EXISTS class_result_barriers(class_id BIGINT PRIMARY KEY,branch_id BIGINT NOT NULL,token VARCHAR(36) NOT NULL,source_revision BIGINT NOT NULL DEFAULT 0,result_revision BIGINT NOT NULL DEFAULT 0,confirmed_count BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS final_results(id BIGINT AUTO_INCREMENT PRIMARY KEY,class_id BIGINT NOT NULL,branch_id BIGINT NOT NULL,enrollment_id BIGINT NOT NULL,student_id BIGINT NOT NULL,revision BIGINT NOT NULL,policy_revision BIGINT NOT NULL,academic_source_revision BIGINT NOT NULL,teaching_source_revision BIGINT NOT NULL,request_id VARCHAR(36) NOT NULL,fingerprint VARCHAR(64) NOT NULL,outcome VARCHAR(20) NOT NULL,state VARCHAR(20) NOT NULL,reason VARCHAR(500) NOT NULL,confirmed_by BIGINT NOT NULL,confirmed_by_name VARCHAR(255) NOT NULL,confirmed_at DATETIME(6) NOT NULL,snapshot LONGTEXT NOT NULL,reopened_by BIGINT NULL,reopened_by_name VARCHAR(255) NULL,reopened_at DATETIME(6) NULL,reopen_reason VARCHAR(500) NULL,UNIQUE KEY uk_final_revision(enrollment_id,revision),UNIQUE KEY uk_final_request(request_id),KEY idx_final_class(class_id,id),KEY idx_final_student(student_id,id));
CREATE TABLE IF NOT EXISTS result_reopens(request_id VARCHAR(36) PRIMARY KEY,class_id BIGINT NOT NULL,previous_revision BIGINT NOT NULL,actor_id BIGINT NOT NULL,actor_name VARCHAR(255) NOT NULL,created_at DATETIME(6) NOT NULL,reason VARCHAR(500) NOT NULL);
CREATE TABLE IF NOT EXISTS class_closures(class_id BIGINT PRIMARY KEY,revision BIGINT NOT NULL,closed BIT NOT NULL,actor_name VARCHAR(255) NOT NULL,actor_id BIGINT NOT NULL,changed_at DATETIME(6) NOT NULL,reason VARCHAR(500) NOT NULL);
CREATE TABLE IF NOT EXISTS class_closure_events(request_id VARCHAR(36) PRIMARY KEY,class_id BIGINT NOT NULL,expected_revision BIGINT NOT NULL,revision BIGINT NOT NULL,closed BIT NOT NULL,actor_name VARCHAR(255) NOT NULL,actor_id BIGINT NOT NULL,changed_at DATETIME(6) NOT NULL,reason VARCHAR(500) NOT NULL,UNIQUE KEY uk_closure_revision(class_id,revision));
SET @lc_result_sql=(SELECT IF(COUNT(*)=0,'ALTER TABLE class_closures ADD COLUMN result_revision BIGINT NOT NULL DEFAULT 0','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='class_closures' AND column_name='result_revision');
PREPARE lc_result_stmt FROM @lc_result_sql;EXECUTE lc_result_stmt;DEALLOCATE PREPARE lc_result_stmt;
SET @lc_result_sql=(SELECT IF(COUNT(*)=0,'ALTER TABLE class_closures ADD COLUMN source_revision BIGINT NOT NULL DEFAULT 0','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='class_closures' AND column_name='source_revision');
PREPARE lc_result_stmt FROM @lc_result_sql;EXECUTE lc_result_stmt;DEALLOCATE PREPARE lc_result_stmt;
SET @lc_result_sql=(SELECT IF(COUNT(*)=0,'ALTER TABLE final_results ADD COLUMN current_enrollment_id BIGINT GENERATED ALWAYS AS (CASE WHEN state = ''CONFIRMED'' THEN enrollment_id ELSE NULL END) STORED','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='final_results' AND column_name='current_enrollment_id');
PREPARE lc_result_stmt FROM @lc_result_sql;EXECUTE lc_result_stmt;DEALLOCATE PREPARE lc_result_stmt;
SET @lc_result_sql=(SELECT IF(COUNT(*)=0,'ALTER TABLE final_results ADD UNIQUE KEY uk_final_current(current_enrollment_id)','SELECT 1') FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='final_results' AND index_name='uk_final_current');
PREPARE lc_result_stmt FROM @lc_result_sql;EXECUTE lc_result_stmt;DEALLOCATE PREPARE lc_result_stmt;
